settings.custom_css:
.scroll-left{
    opacity: 0;
    transition: 0.5s all;
    transform: translate3d(-30px, 0, 0);
}

.scroll-right{
    opacity: 0;
    transition: 0.5s all;
    transform: translate3d(30px, 0, 0);
}

.scroll-bottom{
    opacity: 0;
    transition: 0.5s all;
    transform: translate3d(0, 80px, 0);
}

.scroll-top{
    opacity: 0;
    transition: 0.5s all;
    transform: translate3d(0, -80px, 0);
}

.ativo{
    opacity: 1;
    transition: 0.5s all;
    transform: translate3d(0, 0, 0);
}

.flutuar {
  animation: flutuar 3s ease-in-out infinite;
}

@keyframes flutuar {
  0%, 100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-10px);
  }
}

