.pulsar {
  animation: pulsar 1.5s ease-in-out infinite;
}

.pulsar:hover {
  animation-play-state: paused;
}

@keyframes pulsar {
  0%, 100% {
    transform: scale(1);
  }
  50% {
    transform: scale(1.1);
  }
}
